    public static func decodeSlotSettledEvent(_ log: EventLog) throws -> SlotSettledEvent {
        let event = try _eventSlotSettled()
        guard log.topics.count == 3 else { throw WrapperError.eventMismatch }
        guard log.topics.first == event.topic else { throw WrapperError.eventMismatch }
        guard let decoded = ABIDecoder.decode(types: event.inputs.filter { !$0.indexed }.map { $0.type }, data: log.data) else { throw WrapperError.invalidValue("SlotSettled(bytes32,address,bytes32,uint256)") }
        let topic0 = log.topics[1]
        guard topic0.count == 32 else { throw WrapperError.invalidValue("event topic 0") }
        guard let raw0 = ABIDecoder.decode(types: [event.inputs[0].type], data: topic0)?.first else { throw WrapperError.invalidValue("event field 0") }
        let value0 = try _cast(raw0, as: Data.self)
        let topic1 = log.topics[2]
        guard topic1.count == 32 else { throw WrapperError.invalidValue("event topic 1") }
        guard let raw1 = ABIDecoder.decode(types: [event.inputs[1].type], data: topic1)?.first else { throw WrapperError.invalidValue("event field 1") }
        let value1 = try _cast(raw1, as: EthereumAddress.self)
        let value2 = try _cast(decoded[0], as: Data.self)
        let value3 = try _cast(decoded[1], as: BigUInt.self)
        return SlotSettledEvent(marketId: value0, winner: value1, registrationDigest: value2, priceUsdc: value3)
    }

    /// A decoded custom ABI error.
    public enum DecodedCustomError {
        /// `AuctionNotSettled()`.
        case auctionNotSettled(AuctionNotSettledError)
        /// `InvalidPerpRegistrationV1()`.
        case invalidPerpRegistrationV1(InvalidPerpRegistrationV1Error)
        /// `IssuanceAuctionCallFailed()`.
        case issuanceAuctionCallFailed(IssuanceAuctionCallFailedError)
        /// `RegistrationConflict()`.
        case registrationConflict(RegistrationConflictError)
    }

    /// Decodes a custom revert payload, or returns nil for an unknown selector.
    public static func decodeCustomError(_ data: Data) throws -> DecodedCustomError? {
        guard data.count >= 4 else { throw WrapperError.invalidValue("error selector") }
        let contract = try _contract()
        let selector = Data(data.prefix(4))
        if selector == Data([0x47, 0x2f, 0xd1, 0x99]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "AuctionNotSettled()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("AuctionNotSettled()") }
            return .auctionNotSettled(AuctionNotSettledError())
        }
        if selector == Data([0x97, 0xbb, 0x06, 0x17]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "InvalidPerpRegistrationV1()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("InvalidPerpRegistrationV1()") }
            return .invalidPerpRegistrationV1(InvalidPerpRegistrationV1Error())
        }
        if selector == Data([0x4d, 0xdd, 0x41, 0x9d]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "IssuanceAuctionCallFailed()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("IssuanceAuctionCallFailed()") }
            return .issuanceAuctionCallFailed(IssuanceAuctionCallFailedError())
        }
        if selector == Data([0x54, 0xdd, 0xad, 0xaf]) {
            guard let error = contract.abi.compactMap({ element -> ABI.Element.EthError? in
                if case .error(let value) = element { return value }
                return nil
            }).first(where: { $0.signature == "RegistrationConflict()" }), error.decodeEthError(Data(data.dropFirst(4))) != nil else { throw WrapperError.invalidValue("RegistrationConflict()") }
            return .registrationConflict(RegistrationConflictError())
        }
        return nil
    }
}
